// Vehicle69:20 controls and actual numeric muzzle helpers. Other prelude
// animations and the already separate projectile allocators are recorded calls.
import ghidra.app.emulator.EmulatorHelper;import java.io.*;import java.util.*;
public class ZNativeHardwarePointOracle extends ZNativeWorldEffectOracle{
 static final long U=0x5e30c8,W=0x1900000,G=0x60ec00,P=0x1910000;int scenario,sync,aim,apc;long shots;
 long mix(long h,long v){return ((h^(v&0xffffffffL))*16777619)&0xffffffffL;}
 void invoke(EmulatorHelper e)throws Exception{sync=aim=apc=0;shots=2166136261L;e.writeRegister("ESP",S);put(e,S,4,RET);put(e,S+4,4,U);for(long p:new long[]{RET,0x45b470,0x45b610,0x45c210,0x45bf90,0x45b050,0x447da0,0x464e80,0x4648a0,0x458620})e.setBreakpoint(toAddr(p));if(!e.run(toAddr(0x45c5c0),null,monitor))throw new Exception(e.getLastError());while(e.readRegister("EIP").longValue()!=RET){long pc=e.readRegister("EIP").longValue(),sp=e.readRegister("ESP").longValue();long result=0;if(pc==0x45b050)aim++;else if(pc==0x447da0){apc++;put(e,U+123,1,(scenario*13)&255);}else if(pc==0x458620)sync++;else if(pc==0x464e80||pc==0x4648a0){boolean rocket=pc==0x4648a0;long[]v=new long[8];v[0]=rocket?1:0;for(int i=0;i<4;i++)v[i+1]=(short)(rocket?read(e,sp+4+i*4,4):i==0?e.readRegister("EDX").longValue():read(e,sp+i*4,4));v[5]=(byte)read(e,sp+(rocket?20:16),4);v[6]=rocket?(int)read(e,sp+24,4):(byte)read(e,0x622be7,1);v[7]=(scenario%3==0?1:0);for(long n:v)shots=mix(shots,n);long out=read(e,sp+(rocket?28:20),4);put(e,out,4,P);put(e,P+35,1,5);result=v[7];}e.writeRegister("EAX",result);long ret=read(e,sp,4);e.writeRegister("ESP",sp+4);if(!e.run(toAddr(ret),null,monitor))throw new Exception(e.getLastError());}}
 public void run()throws Exception{try(PrintWriter out=new PrintWriter(getScriptArgs()[0])){EmulatorHelper e=new EmulatorHelper(currentProgram);try{int[]families={6,25,30,24,32,34,36,38};int[][]delta={{0,-70},{70,-70},{70,0},{70,70},{0,70},{-70,70},{-70,0},{-70,-70}};for(scenario=0;scenario<8192;scenario++){int s=scenario;e.writeMemory(toAddr(U),new byte[192]);e.writeMemory(toAddr(W),new byte[44]);e.writeMemory(toAddr(G),new byte[72]);put(e,0x632194,4,G);put(e,U+8,4,W);put(e,U+48,1,families[s%8]);put(e,U+105,1,32+(s/8%2)*128);put(e,U+123,1,new int[]{0,1,127,128,255}[s/16%5]);put(e,U+44,2,500);put(e,U+46,2,600);int d=s/80%8;put(e,U+80,4,500+delta[d][0]);put(e,U+84,2,600+delta[d][1]);put(e,U+57,1,s/640%8);put(e,U+61,1,7);put(e,U+121,1,s*13);put(e,U+49,1,4);put(e,W+14,2,111);put(e,W+16,2,222);put(e,W+21,1,3);put(e,W+34,1,37);put(e,W+32,1,s*17);invoke(e);out.println("{\"scenario\":"+s+",\"reload\":"+(byte)read(e,U+123,1)+",\"timer\":"+read(e,U+61,1)+",\"turret\":"+read(e,W+21,1)+",\"w22\":"+read(e,W+34,1)+",\"wx\":"+(short)read(e,W+14,2)+",\"wy\":"+(short)read(e,W+16,2)+",\"sync\":"+sync+",\"aim\":"+aim+",\"apc\":"+apc+",\"shots\":"+shots+"}");}}finally{e.dispose();}}}
}
